   406	        _startTime = BlackTimeLibrary.epochStart(_startTime);
   407	        require(_startTime + genesisInfo.duration - BlackTimeLibrary.NO_GENESIS_DEPOSIT_WINDOW > block.timestamp, "TIME");
   408	        genesisInfo.startTime = _startTime;
