   154	        require(genesisInfo.startTime + genesisInfo.duration - BlackTimeLibrary.NO_GENESIS_DEPOSIT_WINDOW > block.timestamp, "TIME");
   155	
   156	        address pairAddress = pairFactory.getPair(nativeToken, genesisInfo.fundingToken, genesisInfo.stable);
   157	        if (pairAddress == address(0)) {
   158	            pairAddress = pairFactory.createPair(nativeToken, genesisInfo.fundingToken, genesisInfo.stable);
