   165	        liveNativeTokens.push(nativeToken);
   166	        liveNativeTokensIndex[nativeToken] = liveNativeTokens.length; // becuase default valie is 0, so starting with 1
   167	
   168	        IGenesisPool(genesisPool).approvePool(pairAddress);
