   186	    // at epoch flip, PRE_LISTING -> PRE_LAUNCH (condition met) , PRE_LAUNCH_DDEPOSIT_DISBALED -> LAUNCH or PARTIALLY_LAUNCH
   187	    function checkAtEpochFlip() external {
   188	        require(epochController == msg.sender, "NA");
   189	
   190	        uint256 _proposedTokensCnt = liveNativeTokens.length;
   191	        uint256 i;
   192	        address _genesisPool;
   193	        PoolStatus _poolStatus;
   194	        address nativeToken;
   195	
   196	        for(i = _proposedTokensCnt; i > 0; i--){
   197	            nativeToken = liveNativeTokens[i-1];
   198	            _genesisPool = genesisFactory.getGenesisPool(nativeToken);
   199	            _poolStatus = IGenesisPool(_genesisPool).poolStatus();
   200	
   201	            if(_poolStatus == PoolStatus.PRE_LISTING && IGenesisPool(_genesisPool).eligbleForPreLaunchPool()){
   202	                tokenHandler.whitelistToken(nativeToken);
   203	                _preLaunchPool(_genesisPool);
   204	            }else if(_poolStatus == PoolStatus.PRE_LAUNCH_DEPOSIT_DISABLED){
   205	                _launchPool(nativeToken, _genesisPool);
   206	            }
   207	        }
   208	    }
