   211	    function _preLaunchPool(address genesisPool) internal {
   212	        address _poolAddress = IGenesisPool(genesisPool).getLiquidityPoolInfo().pairAddress;
   213	        (address _gauge, address _internal_bribe, address _external_bribe) = gaugeManager.createGauge(_poolAddress, 0);
   214	
