   218	    function _launchPool(address _nativeToken, address _genesisPool) internal {
   219	        LiquidityPool memory liquidityPool = IGenesisPool(_genesisPool).getLiquidityPoolInfo();
   220	        pairFactory.setGenesisStatus(liquidityPool.pairAddress, false);
   221	        IGauge(liquidityPool.gaugeAddress).setGenesisPool(_genesisPool);
   222	        IGenesisPool(_genesisPool).launch(router, MATURITY_TIME);
   223	        _removeLiveToken(_nativeToken);
   224	    }
