   226	    // before 3 hrs
   227	    function checkBeforeEpochFlip() external {
   228	        require(epochController == msg.sender, "NA");
   229	
   230	        uint _period = pre_epoch_period;
   231	        if (block.timestamp >= _period + WEEK) { 
   232	            
   233	            uint256 _proposedTokensCnt = liveNativeTokens.length;
   234	            uint256 i;
   235	            address _genesisPool;
   236	            PoolStatus _poolStatus;
   237	            address nativeToken;
   238	            
   239	            for(i = _proposedTokensCnt; i > 0; i--){
   240	                nativeToken = liveNativeTokens[i-1];
   241	                _genesisPool = genesisFactory.getGenesisPool(nativeToken);
   242	                _poolStatus = IGenesisPool(_genesisPool).poolStatus();
   243	
   244	                if(_poolStatus == PoolStatus.PRE_LISTING && IGenesisPool(_genesisPool).eligbleForDisqualify()){
   245	                    pairFactory.setGenesisStatus(IGenesisPool(_genesisPool).getLiquidityPoolInfo().pairAddress, false);
   246	                    IGenesisPool(_genesisPool).setPoolStatus(PoolStatus.NOT_QUALIFIED);
   247	                    _removeLiveToken(nativeToken);
   248	                }
   249	                else if(_poolStatus == PoolStatus.PRE_LAUNCH){
   250	                    IGenesisPool(_genesisPool).setPoolStatus(PoolStatus.PRE_LAUNCH_DEPOSIT_DISABLED);
   251	                }
   252	            }
   253	            pre_epoch_period = BlackTimeLibrary.currPreEpoch(block.timestamp);
   254	        }
   255	    }
