   261	        {
   262	            address replacingAddress = liveNativeTokens[length - 1];
   263	            liveNativeTokens[index - 1] = replacingAddress;
   264	            liveNativeTokens.pop();
   265	            liveNativeTokensIndex[replacingAddress] = index;
   266	        }
   267	    }
