    98	    /// @notice Read earned amount given a tokenID and _rewardToken
    99	    function earned(uint256 tokenId, address _rewardToken) public view returns(uint256){
   100	        if (numCheckpoints[tokenId] == 0) {
   101	            return 0;
   102	        }
   103	        
   104	        uint256 reward = 0;
   105	        uint256 _supply = 1;
   106	        uint256 _currTs = BlackTimeLibrary.epochStart(lastEarn[_rewardToken][tokenId]); // take epoch last claimed in as starting point
   107	        uint256 _index = getPriorBalanceIndex(tokenId, _currTs);
   108	        Checkpoint memory cp0 = checkpoints[tokenId][_index];
   109	        
   110	        
   111	        // accounts for case where lastEarn is before first checkpoint
   112	        _currTs = Math.max(_currTs, BlackTimeLibrary.epochStart(cp0.timestamp));
   113	
   114	        // get epochs between current epoch and first checkpoint in same epoch as last claim
   115	        uint256 numEpochs = (BlackTimeLibrary.epochStart(block.timestamp) - _currTs) / WEEK;
   116	
   117	        if (numEpochs > 0) {
   118	            for (uint256 i = 0; i < numEpochs; i++) {
   119	                // get index of last checkpoint in this epoch
   120	                _index = getPriorBalanceIndex(tokenId, _currTs + WEEK - 1);
   121	                // get checkpoint in this epoch
   122	                cp0 = checkpoints[tokenId][_index];
   123	                // get supply of last checkpoint in this epoch
   124	                _supply = Math.max(supplyCheckpoints[getPriorSupplyIndex(_currTs + WEEK - 1)].supply, 1);
   125	                reward += (cp0.balanceOf * tokenRewardsPerEpoch[_rewardToken][_currTs]) / _supply;
   126	                _currTs += WEEK;
   127	            }
   128	        } 
   129	        return reward;  
   130	    }
