   133	    function getPriorBalanceIndex(uint256 tokenId, uint256 timestamp) public view returns (uint256) {
   134	        uint256 nCheckpoints = numCheckpoints[tokenId];
   135	        if (nCheckpoints == 0) {
   136	            return 0;
   137	        }
   138	
   139	        // First check most recent balance
   140	        if (checkpoints[tokenId][nCheckpoints - 1].timestamp <= timestamp) {
   141	            return (nCheckpoints - 1);
   142	        }
   143	
   144	        // Next check implicit zero balance
   145	        if (checkpoints[tokenId][0].timestamp > timestamp) {
   146	            return 0;
   147	        }
   148	
   149	        uint256 lower = 0;
   150	        uint256 upper = nCheckpoints - 1;
   151	        while (upper > lower) {
   152	            uint256 center = upper - (upper - lower) / 2; // ceil, avoiding overflow
   153	            Checkpoint memory cp = checkpoints[tokenId][center];
   154	            if (cp.timestamp == timestamp) {
   155	                return center;
   156	            } else if (cp.timestamp < timestamp) {
   157	                lower = center;
   158	            } else {
   159	                upper = center - 1;
   160	            }
   161	        }
   162	        return lower;
   163	    }
   164	
   165	    function getPriorSupplyIndex(uint256 timestamp) public view returns (uint256) {
   166	        uint256 nCheckpoints = supplyNumCheckpoints;
   167	        if (nCheckpoints == 0) {
   168	            return 0;
   169	        }
   170	
   171	        // First check most recent balance
   172	        if (supplyCheckpoints[nCheckpoints - 1].timestamp <= timestamp) {
   173	            return (nCheckpoints - 1);
   174	        }
   175	
   176	        // Next check implicit zero balance
   177	        if (supplyCheckpoints[0].timestamp > timestamp) {
   178	            return 0;
   179	        }
   180	
   181	        uint256 lower = 0;
   182	        uint256 upper = nCheckpoints - 1;
   183	        while (upper > lower) {
   184	            uint256 center = upper - (upper - lower) / 2; // ceil, avoiding overflow
   185	            SupplyCheckpoint memory cp = supplyCheckpoints[center];
   186	            if (cp.timestamp == timestamp) {
   187	                return center;
   188	            } else if (cp.timestamp < timestamp) {
   189	                lower = center;
   190	            } else {
   191	                upper = center - 1;
   192	            }
   193	        }
   194	        return lower;
   195	    }
