   223	    function _writeCheckpoint(uint256 tokenId, uint256 balance) internal {
   224	        uint256 _nCheckPoints = numCheckpoints[tokenId];
   225	        uint256 _timestamp = block.timestamp;
   226	
   227	        if (
   228	            _nCheckPoints > 0 &&
   229	            BlackTimeLibrary.epochStart(checkpoints[tokenId][_nCheckPoints - 1].timestamp) ==
   230	            BlackTimeLibrary.epochStart(_timestamp)
   231	        ) {
   232	            checkpoints[tokenId][_nCheckPoints - 1] = Checkpoint(_timestamp, balance);
   233	        } else {
   234	            checkpoints[tokenId][_nCheckPoints] = Checkpoint(_timestamp, balance);
